def normalize_client_supported_protocols(
    values: Optional[list[str] | tuple[str, ...] | set[str] | str],
) -> set[str]:
    if values is None:
        requested = set(SERVER_DEFAULT_CLIENT_PROTOCOLS)
    elif isinstance(values, str):
        requested = {
            item.strip().lower()
            for item in values.split(",")
            if item.strip()
        }
    else:
        requested = {
            clean_limited_text(item, 40).strip().lower()
            for item in values
            if clean_limited_text(item, 40).strip()
        }
    return requested.intersection(SERVER_CLIENT_READY_PROTOCOLS)


def server_primary_protocol(server: dict) -> str:
    protocols = server.get("protocols") or []
    primary = next(
        (item for item in protocols if isinstance(item, dict) and item.get("primary")),
        None,
    )
    primary = primary or next((item for item in protocols if isinstance(item, dict)), None)
    return str((primary or {}).get("code") or "").strip().lower()


def server_visible_to_client(server: dict, supported_protocols: set[str]) -> bool:
    return server_primary_protocol(server) in supported_protocols


def protocol_catalog_item(
    code: str,
    client_supported_protocols: Optional[set[str]] = None,
) -> dict:
    title = SERVER_PROTOCOL_TITLES.get(code, code)
    negotiated = normalize_client_supported_protocols(client_supported_protocols)
    client_ready = code in negotiated
    rollout_stage = SERVER_TRANSPORT_ROLLOUT_STAGES.get(code, "research")
    return {
        "code": code,
        "title": title,
        "clientReady": client_ready,
        "serverReady": code == "wireguard_udp",
        "publicReady": client_ready and rollout_stage == "public" and code == "wireguard_udp",
        "rolloutStage": rollout_stage,
        "rolloutOrder": SERVER_PROTOCOL_ROLLOUT_ORDER.index(code)
        if code in SERVER_PROTOCOL_ROLLOUT_ORDER
        else 999,
        "status": "ready" if client_ready and code == "wireguard_udp" else "planned",
    }


def build_resilience_policy(
    servers: Optional[list[dict]] = None,
    client_supported_protocols: Optional[set[str]] = None,
) -> dict:
    negotiated = normalize_client_supported_protocols(client_supported_protocols)
    protocol_matrix = [
        protocol_catalog_item(code, negotiated) for code in SERVER_CATALOG_PROTOCOLS
    ]
    route_decision = build_resilience_route_decision(
        [builtin_server_catalog_entry()] if servers is None else servers
    )
    return {
        "autoSwitch": True,
        "strategy": "best_healthy_config_ready",
        "clientRouteProbe": {
            "enabled": False,
            "reason": "client_side_probe_removed_from_android_stable",
        },
        "clientSideQualityGate": {
            "enabled": False,
            "reason": "server_does_not_require_client_youtube_probe_for_connect",
        },
        "adaptiveRouting": {
            "enabled": True,
            "mode": route_decision["mode"],
            "selectionPolicy": route_decision["selectionPolicy"],
            "description": (
                "Backend выбирает самый лёгкий живой способ подключения. "
                "Тяжёлые режимы включаются только когда более простые слои "
                "не проходят свежие проверки."
            ),
        },
        "routeDecision": route_decision,
        "clientReadyProtocols": sorted(negotiated),
        "rolloutOrder": list(SERVER_PROTOCOL_ROLLOUT_ORDER),
        "protocols": protocol_matrix,
        "currentWindowsClient": {
            "canUse": sorted(negotiated),
            "cannotUseYet": [
                item["code"] for item in protocol_matrix if not item["clientReady"]
            ],
            "message": (
                "Windows-клиент сейчас умеет подключаться только к безопасно "
                "выданным WireGuard UDP конфигам. Остальные режимы заведены в "
                "каталог как план rollout и не попадут пользователю без клиента, "
                "серверной установки и проверок."
            ),
        },
        "publicationGate": server_publication_requirements(),
    }


def preview_catalog_allowed(release_channel: Optional[str], app_version: Optional[str] = None) -> bool:
    channel = clean_limited_text(release_channel, 40).strip().lower()
    version = clean_limited_text(app_version, 120).strip().lower()
    return bool(
        channel in {"preview", "internal"}
        or "preview" in version
        or "adgate" in version
    )


def preview_server_ids_for_request(
    release_channel: Optional[str],
    app_version: Optional[str] = None,
) -> set[str]:
    if not PREVIEW_SERVER_IDS:
        return set()
    if not preview_catalog_allowed(release_channel, app_version):
        return set()
    return set(PREVIEW_SERVER_IDS)


def managed_catalog_entry_to_public_server(
    entry: dict,
    *,
    preview_only: bool = False,
) -> dict:
    protocol = entry.get("protocol") or "wireguard_udp"
    transport = entry.get("transport") or "udp"
    public_capacity = public_endpoint_capacity_payload(entry.get("capacity") or {})
    client_config_ready = bool(entry.get("clientConfigReady"))
    preview_available = (
        preview_only
        and str(entry.get("status") or "").strip().lower() == "healthy"
        and client_config_ready
    )
    public_available = bool(entry.get("available")) and (
        bool(entry.get("publicEligible"))
        or managed_catalog_entry_has_resilient_client_visibility(entry)
    )
    return {
        "id": entry.get("serverId") or "",
        "title": entry.get("title") or "VPN-узел Green VPN",
        "subtitle": entry.get("subtitle") or "",
        "country": entry.get("country") or "",
        "city": entry.get("city") or "",
        "provider": entry.get("provider") or "",
        "status": entry.get("status") or "unknown",
        "available": bool(preview_available or public_available),
        "healthScore": int(entry.get("healthScore") or 0),
        "latencyMs": entry.get("latencyMs"),
        "priority": int(entry.get("priority") or 100),
        "capacity": public_capacity,
        "selectionScore": int(entry.get("selectionScore") or 0),
        "endpoint": {
            "host": entry.get("host") or "",
            "port": int(entry.get("port") or 0),
        },
        "protocols": [
            {
                "code": protocol,
                "title": SERVER_PROTOCOL_TITLES.get(protocol, protocol),
                "transport": transport,
                "port": int(entry.get("port") or 0),
                "primary": True,
            }
        ],
        "managed": True,
        "clientConfigReady": client_config_ready,
        "publicEligible": bool(entry.get("publicEligible")),
        "previewOnly": bool(preview_only),
    }


def managed_catalog_entry_has_resilient_client_visibility(entry: dict) -> bool:
    """Keep remote WireGuard nodes visible when only monitoring freshness is stale."""
    if bool(entry.get("publicEligible")):
        return True
    if not bool(entry.get("clientConfigReady")):
        return False
    if not bool(entry.get("available")):
        return False
    if not bool(entry.get("isActive")) or not bool(entry.get("isPublic")):
        return False
    if str(entry.get("clientConfigProfile") or "") != "remote_ssh_wg0":
        return False
    if str(entry.get("status") or "").strip().lower() != "healthy":
        return False
    if str(entry.get("publicationPausedAt") or "").strip():
        return False
    try:
        health_score = int(entry.get("healthScore") or 0)
    except Exception:
        health_score = 0
    return health_score >= SERVER_PUBLIC_MIN_HEALTH_SCORE


def list_public_client_catalog_servers(
    supported_protocols: Optional[set[str]] = None,
) -> list[dict]:
    negotiated = normalize_client_supported_protocols(supported_protocols)
    try:
        managed_entries = list_managed_server_catalog_entries(
            status="healthy",
            active="active",
            public="public",
            limit=100,
            offset=0,
        )
    except Exception:
        return []
    return [
        managed_catalog_entry_to_public_server(entry)
        for entry in managed_entries
        if str(entry.get("protocol") or "").strip().lower() in negotiated
        and entry.get("clientConfigReady")
        and (
            entry.get("publicEligible")
            or managed_catalog_entry_has_resilient_client_visibility(entry)
        )
    ]


def list_preview_client_catalog_servers(
    server_ids: set[str],
    supported_protocols: Optional[set[str]] = None,
) -> list[dict]:
    if not server_ids:
        return []
    negotiated = normalize_client_supported_protocols(supported_protocols)
    try:
        managed_entries = list_managed_server_catalog_entries(
            status="healthy",
            active="all",
            public="all",
            limit=500,
            offset=0,
        )
    except Exception:
        return []
    return [
        managed_catalog_entry_to_public_server(entry, preview_only=True)
        for entry in managed_entries
        if entry.get("serverId") in server_ids
        and str(entry.get("protocol") or "").strip().lower() in negotiated
        and entry.get("clientConfigReady")
    ]


def build_server_catalog(
    *,
    release_channel: Optional[str] = None,
    app_version: Optional[str] = None,
    client_supported_protocols: Optional[list[str] | set[str] | str] = None,
) -> dict:
    negotiated = normalize_client_supported_protocols(client_supported_protocols)
    builtin = builtin_server_catalog_entry()
    managed_servers = [
        item
        for item in list_public_client_catalog_servers(negotiated)
        if item.get("id") != builtin["id"] and server_visible_to_client(item, negotiated)
    ]
    preview_server_ids = preview_server_ids_for_request(release_channel, app_version)
    existing_server_ids = {str(item.get("id") or "") for item in managed_servers}
    preview_servers = [
        item
        for item in list_preview_client_catalog_servers(preview_server_ids, negotiated)
        if item.get("id") != builtin["id"]
        and item.get("id") not in existing_server_ids
        and server_visible_to_client(item, negotiated)
    ]
    builtin_client_ready = bool(builtin.get("available")) and bool(
        builtin.get("clientConfigReady")
    )
    servers = (
        [builtin]
        if builtin_client_ready and server_visible_to_client(builtin, negotiated)
        else []
    ) + managed_servers + preview_servers
    default_candidates = [server for server in servers if server_auto_capacity_ok(server)]
    if not default_candidates:
        default_candidates = [
            server
            for server in servers
            if bool(server.get("available")) and bool(server.get("clientConfigReady"))
        ]
    default_server = (
        sorted(
            default_candidates,
            key=lambda item: (
                server_protocol_preference_rank(item),
                -int(item.get("selectionScore") or endpoint_selection_score(item)),
                int(item.get("priority") or 100),
                -int((item.get("capacity") or {}).get("capacityScore") or 0),
            ),
        )[0]
        if default_candidates
        else None
    )
    default_fallback = servers[0] if servers else builtin
    default_server_id = str(
        (default_server or default_fallback).get("id") or "intelligent_smew"
    )
    return {
        "version": SERVER_CATALOG_VERSION,
        "generatedAt": utc_now_iso(),
        "defaultServerId": default_server_id,
        "auto": {
            "title": "Авто",
            "subtitle": "Выбирает самый здоровый VPN-узел, который умеет текущий клиент",
            "strategy": "best_healthy_config_ready",
        },
        "servers": servers,
        "resilience": build_resilience_policy(servers, negotiated),
        "bootstrap": {
            "apiBaseUrls": SERVER_CATALOG_API_BASE_URLS,
            "emergencyCatalogUrl": SERVER_CATALOG_EMERGENCY_URL,
        },
        "managedCatalog": {
            "enabled": True,
            "mode": "safe_publication_gate",
            "message": (
                "Дополнительные VPN-узлы управляются в админке, но не выдаются "
                "клиенту без готового профиля конфига, свежего мониторинга и rollout gate."
            ),
            "clientVisibleManagedEntries": len(managed_servers),
            "clientVisiblePreviewEntries": len(preview_servers),
            "negotiatedClientProtocols": sorted(negotiated),
            "publicationRules": server_publication_requirements(),
        },
    }


def server_publication_requirements() -> dict:
    return {
        "minHealthScore": SERVER_PUBLIC_MIN_HEALTH_SCORE,
        "maxObservationAgeHours": SERVER_PUBLIC_OBSERVATION_MAX_AGE_HOURS,
        "minHealthyObservations24h": SERVER_PUBLIC_MIN_HEALTHY_OBSERVATIONS,
        "requiredProtocol": "wireguard_udp",
        "clientReadyProtocols": sorted(SERVER_CLIENT_READY_PROTOCOLS),
        "preparedProtocols": list(SERVER_CATALOG_PROTOCOLS),
        "protocolRolloutOrder": list(SERVER_PROTOCOL_ROLLOUT_ORDER),
        "clientConfigProfiles": list(SERVER_CLIENT_CONFIG_PROFILES),
        "requiresActive": True,
        "requiresPublicCandidate": True,
        "requiresClientConfigReady": True,
        "requiresFreshHealthyObservation": True,
        "autoPausesBadPublicCandidates": SERVER_PUBLIC_AUTO_PAUSE_ENABLED,
    }


def normalize_server_catalog_status(value: Optional[str], fallback: str = "draft") -> str:
    candidate = clean_limited_text(value, 40).strip().lower() or fallback
    if candidate not in SERVER_CATALOG_STATUSES:
        raise HTTPException(status_code=400, detail="Неизвестный статус сервера.")
    return candidate


def normalize_server_catalog_protocol(value: Optional[str], fallback: str = "wireguard_udp") -> str:
    candidate = clean_limited_text(value, 40).strip().lower() or fallback
    if candidate not in SERVER_CATALOG_PROTOCOLS:
        raise HTTPException(status_code=400, detail="Неизвестный протокол сервера.")
    return candidate


def normalize_server_catalog_transport(value: Optional[str], fallback: str = "udp") -> str:
    candidate = clean_limited_text(value, 40).strip().lower() or fallback
    if candidate not in SERVER_CATALOG_TRANSPORTS:
        raise HTTPException(status_code=400, detail="Неизвестный транспорт сервера.")
    return candidate


def normalize_server_client_config_profile(
    value: Optional[str],
    fallback: str = "none",
) -> str:
    candidate = clean_limited_text(value, 60).strip().lower() or fallback
    if candidate not in SERVER_CLIENT_CONFIG_PROFILES:
        raise HTTPException(status_code=400, detail="Неизвестный профиль клиентского конфига.")
    return candidate


def normalize_server_id(value: Optional[str]) -> str:
    candidate = clean_limited_text(value, 80).strip().lower()
    if not candidate:
        raise HTTPException(status_code=400, detail="serverId обязателен.")
    if not re.fullmatch(r"[a-z0-9][a-z0-9_-]{2,79}", candidate):
        raise HTTPException(
            status_code=400,
            detail="serverId должен содержать латинские буквы, цифры, дефис или подчёркивание.",
        )
    if candidate in {"auto", "intelligent_smew"}:
        raise HTTPException(status_code=400, detail="serverId зарезервирован.")
    return candidate


def normalize_server_host(value: Optional[str]) -> str:
    host = clean_limited_text(value, 250).strip().lower()
    if not host:
        raise HTTPException(status_code=400, detail="host обязателен.")
    if "/" in host or "\\" in host or " " in host:
        raise HTTPException(status_code=400, detail="host должен быть DNS-именем или IP-адресом.")
    return host


def normalize_server_port(value: Optional[int]) -> int:
    try:
        port = int(value or 0)
    except Exception:
        port = 0
    if port < 1 or port > 65535:
        raise HTTPException(status_code=400, detail="port должен быть в диапазоне 1..65535.")
    return port


def normalize_percentish(value: Optional[int], fallback: int = 0) -> int:
    try:
        parsed = int(value if value is not None else fallback)
    except Exception:
        parsed = fallback
    return max(0, min(100, parsed))


def normalize_priority(value: Optional[int], fallback: int = 100) -> int:
    try:
        parsed = int(value if value is not None else fallback)
    except Exception:
        parsed = fallback
    return max(0, min(10000, parsed))


def server_observation_age_hours(observed_at: Optional[str]) -> Optional[float]:
    observed_dt = parse_dt(observed_at)
    if observed_dt is None:
        return None
    if observed_dt.tzinfo is None:
        observed_dt = observed_dt.replace(tzinfo=timezone.utc)
    return max(0.0, (utc_now() - observed_dt).total_seconds() / 3600)


def server_health_meta_for_entries(
    conn: sqlite3.Connection,
    endpoint_ids: list[str],
) -> dict[str, dict]:
    unique_ids = sorted({endpoint_id for endpoint_id in endpoint_ids if endpoint_id})
    since_24h = (utc_now() - timedelta(hours=24)).isoformat()
    result: dict[str, dict] = {}
    for endpoint_id in unique_ids:
        latest_row = conn.execute(
            """
            SELECT *
            FROM server_health_observations
            WHERE endpoint_id = ?
            ORDER BY observed_at DESC, id DESC
            LIMIT 1
            """,
            (endpoint_id,),
        ).fetchone()
        healthy_24h = conn.execute(
            """
            SELECT COUNT(*)
            FROM server_health_observations
            WHERE endpoint_id = ? AND observed_at >= ? AND status = 'healthy'
            """,
            (endpoint_id, since_24h),
        ).fetchone()[0]
        failed_24h = conn.execute(
            """
            SELECT COUNT(*)
            FROM server_health_observations
            WHERE endpoint_id = ? AND observed_at >= ? AND status IN ('degraded', 'down')
            """,
            (endpoint_id, since_24h),
        ).fetchone()[0]
        latest = server_health_observation_payload(latest_row) if latest_row is not None else None
        result[endpoint_id] = {
            "latest": latest,
            "latestAgeHours": (
                server_observation_age_hours(latest.get("observedAt")) if latest else None
            ),
            "healthyObservations24h": int(healthy_24h or 0),
            "failedObservations24h": int(failed_24h or 0),
        }
    return result


def vpn_node_config_path(server_id: str) -> Path:
    safe_id = clean_limited_text(server_id, 80).strip().lower()
    if not re.fullmatch(r"[a-z0-9][a-z0-9_-]{2,79}", safe_id or ""):
        raise HTTPException(status_code=400, detail="Некорректный serverId для node-конфига.")
    return VPN_NODE_CONFIG_DIR / f"{safe_id}.env"


def parse_server_only_env_file(path: Path) -> dict[str, str]:
    values: dict[str, str] = {}
    try:
        text = path.read_text(encoding="utf-8")
    except FileNotFoundError:
        raise
    except Exception as exc:
        raise HTTPException(
            status_code=500,
            detail=f"Не удалось прочитать server-only node env: {path.name}.",
        ) from exc

    for raw_line in text.splitlines():
        line = raw_line.strip()
        if not line or line.startswith("#"):
            continue
        if line.startswith("export "):
            line = line[len("export ") :].strip()
        if "=" not in line:
            continue
        key, value = line.split("=", 1)
        key = key.strip()
        value = value.strip()
        if (
            len(value) >= 2
            and value[0] == value[-1]
            and value[0] in {"'", '"'}
        ):
            value = value[1:-1]
        if key:
            values[key] = value
    return values


def remote_vpn_node_config_check(
    server_id: str,
    row_host: Optional[str] = None,
    row_port: Optional[int] = None,
) -> tuple[dict, list[dict]]:
    blockers: list[dict] = []

    def add_blocker(code: str, message: str) -> None:
        blockers.append({"code": code, "message": message})

    try:
        path = vpn_node_config_path(server_id)
    except HTTPException as exc:
        add_blocker("remote_node_config_server_id_invalid", str(exc.detail))
        return {}, blockers

    if not path.exists():
        add_blocker(
            "remote_node_config_missing",
            f"Нет server-only env для удалённого VPN-узла: {path}.",
        )
        return {}, blockers

    try:
        env = parse_server_only_env_file(path)
    except HTTPException as exc:
        add_blocker("remote_node_config_unreadable", str(exc.detail))
        return {}, blockers
    except FileNotFoundError:
        add_blocker("remote_node_config_missing", f"Нет server-only env: {path}.")
        return {}, blockers

    ssh_host = (env.get("GREENVPN_NODE_HOST") or "").strip()
    ssh_user = (env.get("GREENVPN_NODE_USER") or "root").strip()
    ssh_port_raw = (env.get("GREENVPN_NODE_PORT") or "22").strip()
    ssh_key_raw = (env.get("GREENVPN_NODE_SSH_KEY") or "").strip()
    public_host = (env.get("GREENVPN_NODE_PUBLIC_HOST") or ssh_host).strip().lower()
    public_port_raw = (env.get("GREENVPN_NODE_PUBLIC_PORT") or str(WG_ENDPOINT_PORT)).strip()
    iface = (env.get("GREENVPN_NODE_WG_INTERFACE") or WG_INTERFACE).strip()
    wg_config = (env.get("GREENVPN_NODE_WG_CONFIG") or "/etc/wireguard/wg0.conf").strip()
    wg_public_key = (env.get("GREENVPN_NODE_WG_PUBLIC_KEY") or "").strip()
    client_mtu_raw = (env.get("GREENVPN_NODE_CLIENT_MTU") or "").strip()
    client_subnet_raw = (env.get("GREENVPN_NODE_CLIENT_SUBNET") or "").strip()
    wg_tool = (env.get("GREENVPN_NODE_WG_TOOL") or "wg").strip()
    awg_field_names = (
        "Jc",
        "Jmin",
        "Jmax",
        "S1",
        "S2",
        "S3",
        "S4",
        "H1",
        "H2",
        "H3",
        "H4",
        "I1",
        "I2",
        "I3",
        "I4",
        "I5",
    )
    awg_interface_fields = {
        field: (env.get(f"GREENVPN_NODE_AWG_{field.upper()}") or "").strip()
        for field in awg_field_names
        if (env.get(f"GREENVPN_NODE_AWG_{field.upper()}") or "").strip()
    }

    try:
        ssh_port = int(ssh_port_raw)
    except Exception:
        ssh_port = 0
    try:
        public_port = int(public_port_raw)
    except Exception:
        public_port = 0
    client_mtu = WG_CLIENT_MTU
    if client_mtu_raw:
        try:
            client_mtu = int(client_mtu_raw)
        except Exception:
            client_mtu = 0
    client_subnet = normalized_ipv4_client_subnet(client_subnet_raw)

    ssh_key = Path(ssh_key_raw) if ssh_key_raw else Path()

    if not ssh_host:
        add_blocker("remote_node_host_missing", "Не задан GREENVPN_NODE_HOST.")
    if not ssh_user:
        add_blocker("remote_node_user_missing", "Не задан GREENVPN_NODE_USER.")
    if ssh_port < 1 or ssh_port > 65535:
        add_blocker("remote_node_port_invalid", "GREENVPN_NODE_PORT должен быть 1..65535.")
    if not ssh_key_raw:
        add_blocker("remote_node_ssh_key_missing", "Не задан GREENVPN_NODE_SSH_KEY.")
    elif not ssh_key.exists():
        add_blocker("remote_node_ssh_key_not_found", "SSH-ключ удалённого узла не найден на backend.")
    if not public_host:
        add_blocker("remote_node_public_host_missing", "Не задан публичный host VPN-узла.")
    if public_port < 1 or public_port > 65535:
        add_blocker("remote_node_public_port_invalid", "Публичный порт VPN-узла должен быть 1..65535.")
    if not iface:
        add_blocker("remote_node_interface_missing", "Не задан WireGuard interface удалённого узла.")
    if not wg_config:
        add_blocker("remote_node_wg_config_missing", "Не задан путь к wg0.conf удалённого узла.")
    if not wg_public_key:
        add_blocker("remote_node_public_key_missing", "Не задан публичный WireGuard-ключ узла.")
    if client_mtu < 576 or client_mtu > 1420:
        add_blocker("remote_node_client_mtu_invalid", "GREENVPN_NODE_CLIENT_MTU должен быть 576..1420.")
    if client_subnet_raw and client_subnet is None:
        add_blocker(
            "remote_node_client_subnet_invalid",
            "GREENVPN_NODE_CLIENT_SUBNET должен быть отдельной IPv4-сетью /16../30.",
        )
    if not wg_tool:
        add_blocker("remote_node_wg_tool_missing", "Не задан инструмент управления VPN-интерфейсом.")
    elif wg_tool != "wg" and not re.fullmatch(r"/[A-Za-z0-9._/+:-]+", wg_tool):
        add_blocker(
            "remote_node_wg_tool_invalid",
            "GREENVPN_NODE_WG_TOOL должен быть wg или абсолютным путём без shell-метасимволов.",
        )

    for field, value in awg_interface_fields.items():
        if field.startswith("I"):
            if len(value) > 2048 or "\n" in value or "\r" in value:
                add_blocker(
                    "remote_node_awg_field_invalid",
                    f"Некорректное значение GREENVPN_NODE_AWG_{field.upper()}.",
                )
            continue
        if not re.fullmatch(r"[0-9]+(?:-[0-9]+)?", value):
            add_blocker(
                "remote_node_awg_field_invalid",
                f"GREENVPN_NODE_AWG_{field.upper()} должен быть числом или числовым диапазоном.",
            )

    normalized_row_host = str(row_host or "").strip().lower()
    if normalized_row_host and public_host and normalized_row_host != public_host:
        add_blocker(
            "remote_node_public_host_mismatch",
            f"host в каталоге ({normalized_row_host}) не совпадает с node env ({public_host}).",
        )
    if row_port is not None and public_port and int(row_port or 0) != public_port:
        add_blocker(
            "remote_node_public_port_mismatch",
            f"port в каталоге ({row_port}) не совпадает с node env ({public_port}).",
        )

    return {
        "serverId": server_id,
        "path": str(path),
        "sshHost": ssh_host,
        "sshUser": ssh_user,
        "sshPort": ssh_port,
        "sshKeyPath": str(ssh_key) if ssh_key_raw else "",
        "publicHost": public_host,
        "publicPort": public_port,
        "interface": iface,
        "wgConfig": wg_config,
        "wgPublicKey": wg_public_key,
        "clientMtu": client_mtu,
        "clientSubnet": str(client_subnet) if client_subnet is not None else "",
        "wgTool": wg_tool,
        "awgInterfaceFields": awg_interface_fields,
    }, blockers


def load_remote_vpn_node_config(server_id: str) -> dict:
    config, blockers = remote_vpn_node_config_check(server_id)
    if blockers:
        raise HTTPException(
            status_code=409,
            detail="Удалённый VPN-узел не готов к выдаче клиентского конфига.",
        )
    return config


def guarded_config_metadata_owned_by_root(metadata: os.stat_result) -> bool:
    return getattr(metadata, "st_uid", 0) == 0


def hysteria2_client_config_check(
    server_id: str,
    *,
    row_host: Optional[str] = None,
    row_port: Optional[int] = None,
) -> tuple[dict, list[dict]]:
    clean_server_id = clean_limited_text(server_id, 80).strip().lower()
    blockers: list[dict] = []

    def add_blocker(code: str, message: str) -> None:
        blockers.append({"code": code, "message": message})

    if clean_server_id not in HYSTERIA2_CANARY_SERVER_IDS:
        add_blocker(
            "hysteria2_server_not_allowlisted",
            "Hysteria2 config разрешён только для явно указанного canary serverId.",
        )
    if not re.fullmatch(r"[a-z0-9][a-z0-9_-]{2,79}", clean_server_id):
        add_blocker("hysteria2_server_id_invalid", "Некорректный Hysteria2 serverId.")
        return {}, blockers

    config_path = HYSTERIA2_CLIENT_CONFIG_ROOT / f"{clean_server_id}.hysteria2.yaml"
    try:
        resolved_root = HYSTERIA2_CLIENT_CONFIG_ROOT.resolve()
        resolved_path = config_path.resolve(strict=False)
        resolved_path.relative_to(resolved_root)
    except (OSError, ValueError):
        add_blocker("hysteria2_config_path_unsafe", "Путь Hysteria2 config вышел за разрешённый root.")
        return {}, blockers

    try:
        if config_path.is_symlink():
            add_blocker("hysteria2_config_symlink_refused", "Hysteria2 config не может быть symlink.")
            return {}, blockers
        metadata = config_path.stat()
        if not config_path.is_file():
            raise FileNotFoundError(str(config_path))
        if not guarded_config_metadata_owned_by_root(metadata):
            add_blocker("hysteria2_config_not_root_owned", "Hysteria2 config должен принадлежать root.")
        if os.name != "nt" and metadata.st_mode & 0o077:
            add_blocker("hysteria2_config_not_root_only", "Hysteria2 config должен иметь mode 0600.")
        if metadata.st_size < 64 or metadata.st_size > 65536:
            add_blocker("hysteria2_config_size_invalid", "Некорректный размер Hysteria2 config.")
        config_text = config_path.read_text(encoding="utf-8")
    except (OSError, UnicodeError):
        add_blocker("hysteria2_config_unreadable", "Root-only Hysteria2 config недоступен.")
        return {"path": str(config_path)}, blockers

    required_patterns = {
        "hysteria2_server_missing": r"(?m)^server:\s*([^\s#]+)\s*$",
        "hysteria2_auth_missing": r"(?m)^auth:\s*[^\s#]+\s*$",
        "hysteria2_tls_missing": r"(?m)^tls:\s*$",
        "hysteria2_sni_missing": r"(?m)^\s+sni:\s*[^\s#]+\s*$",
        "hysteria2_tls_verification_missing": r"(?m)^\s+insecure:\s*false\s*$",
        "hysteria2_obfs_missing": r"(?m)^obfs:\s*$",
        "hysteria2_salamander_missing": r"(?m)^\s+type:\s*salamander\s*$",
        "hysteria2_obfs_password_missing": r"(?m)^\s+password:\s*[^\s#]+\s*$",
    }
    matches: dict[str, re.Match[str]] = {}
    for code, pattern in required_patterns.items():
        match = re.search(pattern, config_text)
        if match is None:
            add_blocker(code, "Hysteria2 client config не прошёл обязательную shape-проверку.")
        else:
            matches[code] = match
    if re.search(r"(?m)^\s+insecure:\s*(true|yes|1)\s*$", config_text, re.IGNORECASE):
        add_blocker("hysteria2_insecure_tls_refused", "Отключение TLS verification запрещено.")
    if re.search(
        r"(?m)^(socks5|http|tun|tcpForwarding|udpForwarding|tcpTProxy|udpTProxy):\s*$",
        config_text,
    ):
        add_blocker(
            "hysteria2_base_config_contains_local_mode",
            "Control-plane хранит только transport base config; local mode добавляет клиентский engine.",
        )

    sni_match = matches.get("hysteria2_sni_missing")
    config_sni = sni_match.group(0).split(":", 1)[1].strip().lower() if sni_match else ""
    if not HYSTERIA2_CANARY_SNI or config_sni != HYSTERIA2_CANARY_SNI:
        add_blocker("hysteria2_sni_not_allowlisted", "TLS SNI не совпадает с canary allowlist.")

    config_host = ""
    config_port = 0
    server_match = matches.get("hysteria2_server_missing")
    if server_match is not None:
        server_value = server_match.group(1).strip()
        try:
            parsed_host, parsed_port = server_value.rsplit(":", 1)
            config_host = parsed_host.strip("[]").lower()
            config_port = int(parsed_port)
            ipaddress.ip_address(config_host)
        except (ValueError, TypeError):
            add_blocker(
                "hysteria2_endpoint_invalid",
                "Hysteria2 endpoint должен быть literal IP:port для Android FD-control.",
            )
    expected_host = str(row_host or "").strip().strip("[]").lower()
    expected_port = int(row_port or 0)
    if expected_host and config_host and expected_host != config_host:
        add_blocker("hysteria2_endpoint_host_mismatch", "Host config не совпадает с catalog row.")
    if expected_port and config_port and expected_port != config_port:
        add_blocker("hysteria2_endpoint_port_mismatch", "Port config не совпадает с catalog row.")

    return {
        "serverId": clean_server_id,
        "path": str(config_path),
        "host": config_host,
        "port": config_port,
        "configText": config_text,
    }, blockers


def load_hysteria2_client_config(server_id: str, *, row_host: str, row_port: int) -> dict:
    config, blockers = hysteria2_client_config_check(
        server_id,
        row_host=row_host,
        row_port=row_port,
    )
    if blockers:
        raise HTTPException(
            status_code=409,
            detail={
                "code": "hysteria2_client_config_not_ready",
                "message": "Hysteria2 canary пока не готов к безопасной выдаче.",
                "blockers": [item["code"] for item in blockers],
            },
        )
    return config


def vless_reality_client_config_check(
    server_id: str,
    *,
    row_host: Optional[str] = None,
    row_port: Optional[int] = None,
) -> tuple[dict, list[dict]]:
    clean_server_id = clean_limited_text(server_id, 80).strip().lower()
    blockers: list[dict] = []

    def add_blocker(code: str, message: str) -> None:
        blockers.append({"code": code, "message": message})

    if clean_server_id not in VLESS_REALITY_CANARY_SERVER_IDS:
        add_blocker(
            "vless_reality_server_not_allowlisted",
            "VLESS REALITY config разрешён только для явно указанного canary serverId.",
        )
    if not re.fullmatch(r"[a-z0-9][a-z0-9_-]{2,79}", clean_server_id):
        add_blocker("vless_reality_server_id_invalid", "Некорректный VLESS REALITY serverId.")
        return {}, blockers

    config_path = VLESS_REALITY_CLIENT_CONFIG_ROOT / f"{clean_server_id}.vless-reality.json"
    try:
        resolved_root = VLESS_REALITY_CLIENT_CONFIG_ROOT.resolve()
        resolved_path = config_path.resolve(strict=False)
        resolved_path.relative_to(resolved_root)
    except (OSError, ValueError):
        add_blocker("vless_reality_config_path_unsafe", "Путь VLESS REALITY config вышел за разрешённый root.")
        return {}, blockers

    try:
        if config_path.is_symlink():
            add_blocker("vless_reality_config_symlink_refused", "VLESS REALITY config не может быть symlink.")
            return {}, blockers
        metadata = config_path.stat()
        if not config_path.is_file():
            raise FileNotFoundError(str(config_path))
        if not guarded_config_metadata_owned_by_root(metadata):
            add_blocker("vless_reality_config_not_root_owned", "VLESS REALITY config должен принадлежать root.")
        if os.name != "nt" and metadata.st_mode & 0o077:
            add_blocker("vless_reality_config_not_root_only", "VLESS REALITY config должен иметь mode 0600.")
        if metadata.st_size < 128 or metadata.st_size > 65536:
            add_blocker("vless_reality_config_size_invalid", "Некорректный размер VLESS REALITY config.")
        config_text = config_path.read_text(encoding="utf-8")
        root = json.loads(config_text)
    except (OSError, UnicodeError, json.JSONDecodeError):
        add_blocker("vless_reality_config_unreadable", "Root-only VLESS REALITY config недоступен или не является JSON.")
        return {"path": str(config_path)}, blockers

    if not isinstance(root, dict):
        add_blocker("vless_reality_config_root_invalid", "VLESS REALITY config должен быть JSON object.")
        return {"path": str(config_path)}, blockers
    if root.get("inbounds") != []:
        add_blocker(
            "vless_reality_base_config_contains_local_listener",
            "Control-plane хранит только base config без локального listener.",
        )

    def has_forbidden_key(value: object) -> bool:
        if isinstance(value, dict):
            for key, child in value.items():
                if str(key).strip().lower() in {"privatekey", "mldsa65seed"}:
                    return True
                if has_forbidden_key(child):
                    return True
        elif isinstance(value, list):
            return any(has_forbidden_key(child) for child in value)
        return False

    if has_forbidden_key(root):
        add_blocker("vless_reality_private_material_refused", "Client config содержит серверный private material.")

    config_host = ""
    config_port = 0
    try:
        outbounds = root["outbounds"]
        if not isinstance(outbounds, list) or not outbounds:
            raise ValueError("outbounds")
        outbound = outbounds[0]
        if outbound.get("protocol") != "vless":
            add_blocker("vless_reality_protocol_invalid", "Первый outbound должен быть VLESS.")
        vnext = outbound["settings"]["vnext"]
        if not isinstance(vnext, list) or len(vnext) != 1:
            raise ValueError("vnext")
        server = vnext[0]
        config_host = str(server["address"]).strip().strip("[]").lower()
        config_port = int(server["port"])
        ipaddress.ip_address(config_host)
        users = server["users"]
        if not isinstance(users, list) or len(users) != 1:
            raise ValueError("users")
        user = users[0]
        if not str(user.get("id") or "").strip():
            add_blocker("vless_reality_client_id_missing", "VLESS client ID отсутствует.")
        if user.get("encryption") != "none":
            add_blocker("vless_reality_encryption_invalid", "VLESS encryption должен быть none.")

        stream = outbound["streamSettings"]
        if stream.get("network") != "xhttp" or stream.get("security") != "reality":
            add_blocker("vless_reality_transport_invalid", "Требуется XHTTP поверх REALITY.")
        reality = stream["realitySettings"]
        server_name = str(reality.get("serverName") or "").strip().lower()
        if not VLESS_REALITY_CANARY_SNI or server_name != VLESS_REALITY_CANARY_SNI:
            add_blocker("vless_reality_sni_not_allowlisted", "REALITY SNI не совпадает с canary allowlist.")
        if not str(reality.get("fingerprint") or "").strip():
            add_blocker("vless_reality_fingerprint_missing", "REALITY fingerprint отсутствует.")
        if not str(reality.get("password") or "").strip():
            add_blocker("vless_reality_password_missing", "REALITY client password отсутствует.")
        short_id = str(reality.get("shortId") or "").strip().lower()
        if not re.fullmatch(r"(?:[0-9a-f]{2}){1,8}", short_id):
            add_blocker("vless_reality_short_id_invalid", "REALITY shortId имеет некорректный формат.")
        xhttp = stream["xhttpSettings"]
        path_value = str(xhttp.get("path") or "").strip()
        if not path_value.startswith("/") or len(path_value) > 256:
            add_blocker("vless_reality_xhttp_path_invalid", "XHTTP path отсутствует или некорректен.")
        if str(xhttp.get("mode") or "auto").strip().lower() not in {"auto", "stream-one"}:
            add_blocker("vless_reality_xhttp_mode_invalid", "XHTTP mode должен быть auto или stream-one.")
    except (KeyError, TypeError, ValueError, IndexError):
        add_blocker("vless_reality_config_shape_invalid", "VLESS REALITY base config не прошёл shape-проверку.")

    expected_host = str(row_host or "").strip().strip("[]").lower()
    expected_port = int(row_port or 0)
    if expected_host and config_host and expected_host != config_host:
        add_blocker("vless_reality_endpoint_host_mismatch", "Host config не совпадает с catalog row.")
    if expected_port and config_port and expected_port != config_port:
        add_blocker("vless_reality_endpoint_port_mismatch", "Port config не совпадает с catalog row.")
    if config_port and config_port != 443:
        add_blocker("vless_reality_endpoint_port_not_443", "VLESS REALITY canary должен использовать TCP/443.")

    return {
        "serverId": clean_server_id,
        "path": str(config_path),
        "host": config_host,
        "port": config_port,
        "root": root,
    }, blockers


def load_vless_reality_client_config(server_id: str, *, row_host: str, row_port: int) -> dict:
    config, blockers = vless_reality_client_config_check(
        server_id,
        row_host=row_host,
        row_port=row_port,
    )
    if blockers:
        raise HTTPException(
            status_code=409,
            detail={
                "code": "vless_reality_client_config_not_ready",
                "message": "VLESS REALITY canary пока не готов к безопасной выдаче.",
                "blockers": [item["code"] for item in blockers],
            },
        )
    root = json.loads(json.dumps(config["root"]))
    root["inbounds"] = [
        {
            "listen": "127.0.0.1",
            "port": 1981,
            "protocol": "socks",
            "settings": {"udp": True},
            "tag": "managed-socks",
        }
    ]
    config["configText"] = json.dumps(root, ensure_ascii=True, indent=2) + "\n"
    config.pop("root", None)
    return config


def guarded_json_client_profile_file(
    config_root: Path,
    filename: str,
    *,
    blocker_prefix: str,
    min_size: int,
) -> tuple[Path, str, dict, list[dict]]:
    blockers: list[dict] = []

    def add_blocker(code: str, message: str) -> None:
        blockers.append({"code": code, "message": message})

    config_path = config_root / filename
    try:
        resolved_root = config_root.resolve()
        resolved_path = config_path.resolve(strict=False)
        resolved_path.relative_to(resolved_root)
    except (OSError, ValueError):
        add_blocker(f"{blocker_prefix}_config_path_unsafe", "Config path escaped its guarded root.")
        return config_path, "", {}, blockers

    try:
        if config_path.is_symlink():
            add_blocker(f"{blocker_prefix}_config_symlink_refused", "Config cannot be a symlink.")
            return config_path, "", {}, blockers
        metadata = config_path.stat()
        if not config_path.is_file():
            raise FileNotFoundError(str(config_path))
        if not guarded_config_metadata_owned_by_root(metadata):
            add_blocker(f"{blocker_prefix}_config_not_root_owned", "Config must be owned by root.")
        if os.name != "nt" and metadata.st_mode & 0o077:
            add_blocker(f"{blocker_prefix}_config_not_root_only", "Config must have mode 0600.")
        if metadata.st_size < min_size or metadata.st_size > 65536:
            add_blocker(f"{blocker_prefix}_config_size_invalid", "Config size is invalid.")
        config_text = config_path.read_text(encoding="utf-8")
        root = json.loads(config_text)
    except (OSError, UnicodeError, json.JSONDecodeError):
        add_blocker(f"{blocker_prefix}_config_unreadable", "Root-only JSON config is unavailable.")
        return config_path, "", {}, blockers

    if not isinstance(root, dict):
        add_blocker(f"{blocker_prefix}_config_root_invalid", "Config root must be a JSON object.")
        return config_path, config_text, {}, blockers
    return config_path, config_text, root, blockers


def naive_https_client_config_check(
    server_id: str,
    *,
    row_host: Optional[str] = None,
    row_port: Optional[int] = None,
) -> tuple[dict, list[dict]]:
    clean_server_id = clean_limited_text(server_id, 80).strip().lower()
    blockers: list[dict] = []

    def add_blocker(code: str, message: str) -> None:
        blockers.append({"code": code, "message": message})

    if clean_server_id not in NAIVE_HTTPS_CANARY_SERVER_IDS:
        add_blocker(
            "naive_https_server_not_allowlisted",
            "Naive HTTPS config is limited to an explicit canary serverId.",
        )
    if not re.fullmatch(r"[a-z0-9][a-z0-9_-]{2,79}", clean_server_id):
        add_blocker("naive_https_server_id_invalid", "Invalid Naive HTTPS serverId.")
        return {}, blockers

    config_path, config_text, root, file_blockers = guarded_json_client_profile_file(
        NAIVE_HTTPS_CLIENT_CONFIG_ROOT,
        f"{clean_server_id}.naive-https.json",
        blocker_prefix="naive_https",
        min_size=64,
    )
    blockers.extend(file_blockers)
    if not root:
        return {"path": str(config_path)}, blockers

    if set(root) != {"listen", "proxy"}:
        add_blocker("naive_https_config_fields_invalid", "Naive HTTPS config fields are invalid.")
    listen = str(root.get("listen") or "").strip()
    if listen != "socks://127.0.0.1:1982":
        add_blocker("naive_https_listener_invalid", "Naive HTTPS listener must be loopback-only.")

    proxy_text = str(root.get("proxy") or "").strip()
    proxy_host = ""
    proxy_port = 0
    try:
        parsed = urllib.parse.urlsplit(proxy_text)
        proxy_host = str(parsed.hostname or "").strip().lower()
        proxy_port = int(parsed.port or 0)
        if parsed.scheme.lower() != "https":
            add_blocker("naive_https_tls_required", "Naive HTTPS proxy must use HTTPS.")
        if parsed.path or parsed.query or parsed.fragment:
            add_blocker("naive_https_proxy_components_invalid", "Naive HTTPS URI has unsupported components.")
        if not parsed.username or not parsed.password:
            add_blocker("naive_https_credentials_missing", "Naive HTTPS credentials are incomplete.")
    except (TypeError, ValueError):
        add_blocker("naive_https_proxy_invalid", "Naive HTTPS proxy URI is invalid.")

    if not NAIVE_HTTPS_CANARY_HOST or proxy_host != NAIVE_HTTPS_CANARY_HOST:
        add_blocker("naive_https_host_not_allowlisted", "Naive HTTPS host does not match the canary allowlist.")
    if proxy_port != 8443:
        add_blocker("naive_https_port_invalid", "Naive HTTPS canary must use TCP/8443.")
    expected_row_host = str(row_host or "").strip().strip("[]").lower()
    allowed_row_hosts = {NAIVE_HTTPS_CANARY_HOST, NAIVE_HTTPS_CANARY_IP.strip().lower()} - {""}
    if expected_row_host and expected_row_host not in allowed_row_hosts:
        add_blocker("naive_https_endpoint_host_mismatch", "Catalog host does not match the guarded canary.")
    if int(row_port or 0) and int(row_port or 0) != proxy_port:
        add_blocker("naive_https_endpoint_port_mismatch", "Catalog port does not match the guarded canary.")

    return {
        "serverId": clean_server_id,
        "path": str(config_path),
        "host": proxy_host,
        "port": proxy_port,
        "configText": config_text.strip() + "\n",
    }, blockers


def load_naive_https_client_config(server_id: str, *, row_host: str, row_port: int) -> dict:
    config, blockers = naive_https_client_config_check(
        server_id,
        row_host=row_host,
        row_port=row_port,
    )
    if blockers:
        raise HTTPException(
            status_code=409,
            detail={
                "code": "naive_https_client_config_not_ready",
                "message": "Naive HTTPS canary is not ready for guarded issue.",
                "blockers": [item["code"] for item in blockers],
            },
        )
    return config


def dnstt_client_config_check(
    server_id: str,
    *,
    row_host: Optional[str] = None,
    row_port: Optional[int] = None,
) -> tuple[dict, list[dict]]:
    clean_server_id = clean_limited_text(server_id, 80).strip().lower()
    blockers: list[dict] = []

    def add_blocker(code: str, message: str) -> None:
        blockers.append({"code": code, "message": message})

    if clean_server_id not in DNSTT_CANARY_SERVER_IDS:
        add_blocker("dnstt_server_not_allowlisted", "dnstt config is limited to an explicit canary serverId.")
    if not re.fullmatch(r"[a-z0-9][a-z0-9_-]{2,79}", clean_server_id):
        add_blocker("dnstt_server_id_invalid", "Invalid dnstt serverId.")
        return {}, blockers

    config_path, config_text, root, file_blockers = guarded_json_client_profile_file(
        DNSTT_CLIENT_CONFIG_ROOT,
        f"{clean_server_id}.dnstt.json",
        blocker_prefix="dnstt",
        min_size=180,
    )
    blockers.extend(file_blockers)
    if not root:
        return {"path": str(config_path)}, blockers

    if set(root) != {"zone", "publicKey", "socks", "resolvers", "expectedEgress"}:
        add_blocker("dnstt_config_fields_invalid", "dnstt config fields are invalid.")
    zone = str(root.get("zone") or "").strip().lower()
    public_key = str(root.get("publicKey") or "").strip().lower()
    expected_egress = str(root.get("expectedEgress") or "").strip()
    if not DNSTT_CANARY_ZONE or zone != DNSTT_CANARY_ZONE:
        add_blocker("dnstt_zone_not_allowlisted", "dnstt zone does not match the canary allowlist.")
    if not re.fullmatch(r"[0-9a-f]{64}", public_key):
        add_blocker("dnstt_public_key_invalid", "dnstt client public key is invalid.")
    if not DNSTT_CANARY_IP or expected_egress != DNSTT_CANARY_IP:
        add_blocker("dnstt_egress_not_allowlisted", "dnstt egress does not match the canary allowlist.")

    socks = root.get("socks")
    if not isinstance(socks, dict) or set(socks) != {"listen", "username", "password"}:
        add_blocker("dnstt_socks_fields_invalid", "dnstt SOCKS fields are invalid.")
    else:
        if str(socks.get("listen") or "").strip() != "127.0.0.1:1983":
            add_blocker("dnstt_listener_invalid", "dnstt listener must be loopback-only.")
        username = str(socks.get("username") or "").strip()
        password = str(socks.get("password") or "").strip()
        if not re.fullmatch(r"[A-Za-z0-9_.-]{3,128}", username):
            add_blocker("dnstt_username_invalid", "dnstt SOCKS username is invalid.")
        if not re.fullmatch(r"[A-Za-z0-9+/=]{16,256}", password):
            add_blocker("dnstt_password_invalid", "dnstt SOCKS password is invalid.")

    allowed_resolvers = {
        ("doh", "https://1.1.1.1/dns-query"),
        ("doh", "https://8.8.8.8/dns-query"),
        ("dot", "1.1.1.1:853"),
    }
    resolvers = root.get("resolvers")
    normalized_resolvers: list[tuple[str, str]] = []
    if not isinstance(resolvers, list) or not 1 <= len(resolvers) <= 3:
        add_blocker("dnstt_resolvers_invalid", "dnstt resolver list is invalid.")
    else:
        for resolver in resolvers:
            if not isinstance(resolver, dict) or set(resolver) != {"mode", "endpoint"}:
                add_blocker("dnstt_resolver_fields_invalid", "dnstt resolver fields are invalid.")
                continue
            item = (
                str(resolver.get("mode") or "").strip().lower(),
                str(resolver.get("endpoint") or "").strip(),
            )
            normalized_resolvers.append(item)
            if item not in allowed_resolvers:
                add_blocker("dnstt_resolver_not_allowlisted", "dnstt resolver is not allowlisted.")
        if len(set(normalized_resolvers)) != len(normalized_resolvers):
            add_blocker("dnstt_resolver_duplicate", "dnstt resolvers must be unique.")
        if not normalized_resolvers or normalized_resolvers[0] != ("doh", "https://1.1.1.1/dns-query"):
            add_blocker("dnstt_primary_doh_invalid", "dnstt primary resolver must be guarded DoH.")

    expected_row_host = str(row_host or "").strip().strip("[]")
    if expected_row_host and expected_row_host != DNSTT_CANARY_IP:
        add_blocker("dnstt_endpoint_host_mismatch", "Catalog host does not match dnstt canary.")
    if int(row_port or 0) and int(row_port or 0) != 53:
        add_blocker("dnstt_endpoint_port_mismatch", "dnstt catalog port must be UDP/53.")

    return {
        "serverId": clean_server_id,
        "path": str(config_path),
        "host": DNSTT_CANARY_IP,
        "port": 53,
        "configText": config_text.strip() + "\n",
    }, blockers


def load_dnstt_client_config(server_id: str, *, row_host: str, row_port: int) -> dict:
    config, blockers = dnstt_client_config_check(
        server_id,
        row_host=row_host,
        row_port=row_port,
    )
    if blockers:
        raise HTTPException(
            status_code=409,
            detail={
                "code": "dnstt_client_config_not_ready",
                "message": "dnstt canary is not ready for guarded issue.",
                "blockers": [item["code"] for item in blockers],
            },
        )
    return config


def server_row_client_config_profile(row: sqlite3.Row) -> str:
    try:
        raw_profile = row["client_config_profile"]
    except Exception:
        raw_profile = "none"
    try:
        return normalize_server_client_config_profile(raw_profile)
    except HTTPException:
        return "none"


def server_client_config_readiness(row: sqlite3.Row) -> dict:
    profile = server_row_client_config_profile(row)
    blockers: list[dict] = []

    def add_blocker(code: str, message: str) -> None:
        blockers.append({"code": code, "message": message})

    if profile == "none":
        add_blocker(
            "client_config_profile_missing",
            "Не выбран профиль выдачи конфига. VPN-узел остаётся только внутренней записью.",
        )
    elif profile == "builtin_wg0":
        host = str(row["host"] or "").strip().lower()
        expected_host = WG_ENDPOINT_HOST.strip().lower()
        port = int(row["port"] or 0)
        if row["protocol"] != "wireguard_udp":
            add_blocker(
                "client_config_protocol_mismatch",
                "Профиль builtin_wg0 поддерживает только WireGuard UDP.",
            )
        if row["transport"] != "udp":
            add_blocker(
                "client_config_transport_mismatch",
                "Профиль builtin_wg0 поддерживает только транспорт UDP.",
            )
        if host != expected_host or port != WG_ENDPOINT_PORT:
            add_blocker(
                "client_config_endpoint_mismatch",
                (
                    "Профиль builtin_wg0 можно включать только для текущего backend "
                    f"VPN-узла {WG_ENDPOINT_HOST}:{WG_ENDPOINT_PORT}."
                ),
            )
    elif profile in {"remote_ssh_wg0", "remote_ssh_awg2"}:
        server_id = str(row["server_id"] or "").strip().lower()
        expected_protocol = "amneziawg" if profile == "remote_ssh_awg2" else "wireguard_udp"
        if row["protocol"] != expected_protocol:
            add_blocker(
                "client_config_protocol_mismatch",
                f"Профиль {profile} поддерживает только протокол {expected_protocol}.",
            )
        if row["transport"] != "udp":
            add_blocker(
                "client_config_transport_mismatch",
                "Профиль remote_ssh_wg0 поддерживает только транспорт UDP.",
            )
        remote_config, remote_blockers = remote_vpn_node_config_check(
            server_id,
            row_host=str(row["host"] or "").strip().lower(),
            row_port=int(row["port"] or 0),
        )
        blockers.extend(remote_blockers)
        if profile == "remote_ssh_awg2":
            required_awg_fields = {"S1", "S2", "H1", "H2", "H3", "H4"}
            missing_awg_fields = sorted(
                required_awg_fields - set((remote_config.get("awgInterfaceFields") or {}).keys())
            )
            if missing_awg_fields:
                add_blocker(
                    "remote_node_awg_fields_missing",
                    "Не заданы обязательные AWG2-параметры: " + ", ".join(missing_awg_fields) + ".",
                )
            if (remote_config.get("wgTool") or "wg") == "wg":
                add_blocker(
                    "remote_node_awg_tool_missing",
                    "Для AWG2 нужен GREENVPN_NODE_WG_TOOL с абсолютным путём к awg.",
                )
            awg_client_subnet = normalized_ipv4_client_subnet(
                remote_config.get("clientSubnet")
            )
            if awg_client_subnet is None:
                add_blocker(
                    "remote_node_client_subnet_missing",
                    "Для AWG2 нужен отдельный GREENVPN_NODE_CLIENT_SUBNET.",
                )
            elif awg_client_subnet.overlaps(legacy_wireguard_client_subnet()):
                add_blocker(
                    "remote_node_client_subnet_overlap",
                    "Диапазон AWG2 не должен пересекаться с production WireGuard.",
                )
    elif profile == "static_hysteria2_canary":
        server_id = str(row["server_id"] or "").strip().lower()
        if row["protocol"] != "hysteria2":
            add_blocker(
                "client_config_protocol_mismatch",
                "Профиль static_hysteria2_canary поддерживает только Hysteria2.",
            )
        if row["transport"] not in {"quic", "http3"}:
            add_blocker(
                "client_config_transport_mismatch",
                "Hysteria2 canary требует transport quic или http3.",
            )
        hysteria_config, hysteria_blockers = hysteria2_client_config_check(
            server_id,
            row_host=str(row["host"] or "").strip().lower(),
            row_port=int(row["port"] or 0),
        )
        blockers.extend(hysteria_blockers)
    elif profile == "static_vless_reality_canary":
        server_id = str(row["server_id"] or "").strip().lower()
        if row["protocol"] != "vless_reality":
            add_blocker(
                "client_config_protocol_mismatch",
                "Профиль static_vless_reality_canary поддерживает только VLESS REALITY.",
            )
        if row["transport"] != "reality":
            add_blocker(
                "client_config_transport_mismatch",
                "VLESS REALITY canary требует transport reality.",
            )
        vless_reality_config, vless_reality_blockers = vless_reality_client_config_check(
            server_id,
            row_host=str(row["host"] or "").strip().lower(),
            row_port=int(row["port"] or 0),
        )
        blockers.extend(vless_reality_blockers)
    elif profile == "static_naive_https_canary":
        server_id = str(row["server_id"] or "").strip().lower()
        if row["protocol"] != "naive_https":
            add_blocker(
                "client_config_protocol_mismatch",
                "static_naive_https_canary supports only naive_https.",
            )
        if row["transport"] != "https":
            add_blocker(
                "client_config_transport_mismatch",
                "Naive HTTPS canary requires transport https.",
            )
        naive_https_config, naive_https_blockers = naive_https_client_config_check(
            server_id,
            row_host=str(row["host"] or "").strip().lower(),
            row_port=int(row["port"] or 0),
        )
        blockers.extend(naive_https_blockers)
    elif profile == "static_dnstt_canary":
        server_id = str(row["server_id"] or "").strip().lower()
        if row["protocol"] != "dnstt":
            add_blocker(
                "client_config_protocol_mismatch",
                "static_dnstt_canary supports only dnstt.",
            )
        if row["transport"] != "doh":
            add_blocker(
                "client_config_transport_mismatch",
                "dnstt canary requires transport doh.",
            )
        dnstt_config, dnstt_blockers = dnstt_client_config_check(
            server_id,
            row_host=str(row["host"] or "").strip().lower(),
            row_port=int(row["port"] or 0),
        )
        blockers.extend(dnstt_blockers)
    else:
        add_blocker(
            "client_config_profile_unknown",
            "Неизвестный профиль выдачи конфига. VPN-узел заблокирован до ручной проверки.",
        )

    if profile in {"remote_ssh_wg0", "remote_ssh_awg2"} and "remote_config" in locals() and remote_config:
        expected_endpoint = {
            "host": remote_config.get("publicHost") or row["host"],
            "port": remote_config.get("publicPort") or int(row["port"] or 0),
            "interface": remote_config.get("interface") or WG_INTERFACE,
            "nodeEnv": remote_config.get("path") or "",
        }
        managed_by = profile
    elif profile == "static_hysteria2_canary" and "hysteria_config" in locals() and hysteria_config:
        expected_endpoint = {
            "host": hysteria_config.get("host") or row["host"],
            "port": hysteria_config.get("port") or int(row["port"] or 0),
            "configPath": hysteria_config.get("path") or "",
        }
        managed_by = profile
    elif (
        profile == "static_vless_reality_canary"
        and "vless_reality_config" in locals()
        and vless_reality_config
    ):
        expected_endpoint = {
            "host": vless_reality_config.get("host") or row["host"],
            "port": vless_reality_config.get("port") or int(row["port"] or 0),
            "configPath": vless_reality_config.get("path") or "",
        }
        managed_by = profile
    elif (
        profile == "static_naive_https_canary"
        and "naive_https_config" in locals()
        and naive_https_config
    ):
        expected_endpoint = {
            "host": naive_https_config.get("host") or row["host"],
            "port": naive_https_config.get("port") or int(row["port"] or 0),
            "configPath": naive_https_config.get("path") or "",
        }
        managed_by = profile
    elif profile == "static_dnstt_canary" and "dnstt_config" in locals() and dnstt_config:
        expected_endpoint = {
            "host": dnstt_config.get("host") or row["host"],
            "port": dnstt_config.get("port") or int(row["port"] or 0),
            "configPath": dnstt_config.get("path") or "",
        }
        managed_by = profile
    else:
        expected_endpoint = {
            "host": WG_ENDPOINT_HOST,
            "port": WG_ENDPOINT_PORT,
            "interface": WG_INTERFACE,
        }
        managed_by = "backend_wg0" if profile == "builtin_wg0" else "manual"

    return {
        "ready": not blockers,
        "profile": profile,
        "title": SERVER_CLIENT_CONFIG_PROFILE_TITLES.get(profile, profile),
        "blockers": blockers,
        "managedBy": managed_by,
        "expectedEndpoint": expected_endpoint,
    }


def safe_row_int(row: sqlite3.Row, key: str, fallback: Optional[int] = None) -> Optional[int]:
    try:
        raw = row[key]
    except Exception:
        return fallback
    if raw is None:
        return fallback
    try:
        return int(raw)
    except Exception:
        return fallback


def safe_row_text(row: sqlite3.Row, key: str, fallback: str = "") -> str:
    try:
        raw = row[key]
    except Exception:
        return fallback
    return str(raw or fallback)


def endpoint_capacity_payload(
    bandwidth_mbps: Optional[int],
    reserved_mbps: Optional[int],
    current_load_mbps: Optional[int],
    active_clients: Optional[int],
    assigned_users: Optional[int],
    load_updated_at: Optional[str],
) -> dict:
    planned = max(1, int(bandwidth_mbps or SERVER_DEFAULT_BANDWIDTH_MBPS))
    reserved = max(0, min(int(reserved_mbps if reserved_mbps is not None else SERVER_DEFAULT_RESERVED_MBPS), planned - 1))
    usable = max(1, planned - reserved)
    load = max(0, int(current_load_mbps or 0))
    utilization = round((load / usable) * 100) if usable else 100
    if utilization >= SERVER_CAPACITY_RED_MIN_PERCENT:
        status = "red"
        score = 0
    elif utilization > SERVER_CAPACITY_GREEN_MAX_PERCENT:
        status = "yellow"
        span = max(1, SERVER_CAPACITY_RED_MIN_PERCENT - SERVER_CAPACITY_GREEN_MAX_PERCENT)
        score = max(10, round(70 - (((utilization - SERVER_CAPACITY_GREEN_MAX_PERCENT) / span) * 45)))
    else:
        status = "green"
        score = max(70, min(100, 100 - round((utilization / max(1, SERVER_CAPACITY_GREEN_MAX_PERCENT)) * 20)))
    return {
        "plannedBandwidthMbps": planned,
        "reservedBandwidthMbps": reserved,
        "usableBandwidthMbps": usable,
        "currentLoadMbps": load,
        "freeBandwidthMbps": max(0, usable - load),
        "utilizationPercent": utilization,
        "capacityStatus": status,
        "capacityScore": score,
        "activeClients": max(0, int(active_clients or 0)),
        "assignedUsers": max(0, int(assigned_users or 0)),
        "loadUpdatedAt": load_updated_at or "",
        "greenMaxUtilizationPercent": SERVER_CAPACITY_GREEN_MAX_PERCENT,
        "redMinUtilizationPercent": SERVER_CAPACITY_RED_MIN_PERCENT,
    }


def public_endpoint_capacity_payload(capacity: dict) -> dict:
    raw_score = capacity.get("capacityScore") if isinstance(capacity, dict) else None
    try:
        score = int(raw_score if raw_score is not None else 100)
    except Exception:
        score = 100
    raw_status = str((capacity or {}).get("capacityStatus") or "green").strip().lower()
    if raw_status not in {"green", "yellow", "red"}:
        raw_status = "green"
    return {
        "capacityStatus": raw_status,
        "capacityScore": max(0, min(score, 100)),
        "greenMaxUtilizationPercent": SERVER_CAPACITY_GREEN_MAX_PERCENT,
        "redMinUtilizationPercent": SERVER_CAPACITY_RED_MIN_PERCENT,
    }


def endpoint_selection_score(server: dict) -> int:
    capacity = server.get("capacity") if isinstance(server.get("capacity"), dict) else {}
    health = int(server.get("healthScore") or 0)
    capacity_score = int(capacity.get("capacityScore") if capacity else 100)
    latency = server.get("latencyMs")
    try:
        latency_penalty = min(25, max(0, int(latency or 0) // 20))
    except Exception:
        latency_penalty = 8
    priority = int(server.get("priority") or 100)
    priority_bonus = max(0, 20 - min(20, priority // 5))
    score = round((health * 0.45) + (capacity_score * 0.40) + priority_bonus - latency_penalty)
    if capacity.get("capacityStatus") == "red":
        score = min(score, 20)
    return max(0, min(100, score))


def server_protocol_preference_rank(server: dict) -> int:
    protocol = server_primary_protocol(server)
    try:
        return SERVER_PROTOCOL_ROLLOUT_ORDER.index(protocol)
    except ValueError:
        return len(SERVER_PROTOCOL_ROLLOUT_ORDER) + 100


def server_public_eligibility(row: sqlite3.Row, health_meta: Optional[dict] = None) -> dict:
    meta = health_meta or {}
    latest = meta.get("latest")
    blockers: list[dict] = []

    def add_blocker(code: str, message: str) -> None:
        blockers.append({"code": code, "message": message})

    is_active = bool(row["is_active"])
    is_public = bool(row["is_public"])
    status = row["status"]
    protocol = row["protocol"]
    health_score = int(row["health_score"] or 0)
    healthy_24h = int(meta.get("healthyObservations24h") or 0)
    failed_24h = int(meta.get("failedObservations24h") or 0)
    latest_age_hours = meta.get("latestAgeHours")
    config_readiness = server_client_config_readiness(row)

    if not is_active:
        add_blocker("inactive", "VPN-узел выключен в админке.")
    if not is_public:
        add_blocker("not_public_candidate", "VPN-узел пока не отмечен кандидатом в публичный каталог.")
    if status != "healthy":
        add_blocker("status_not_healthy", f"Статус VPN-узла сейчас {status}.")
    if health_score < SERVER_PUBLIC_MIN_HEALTH_SCORE:
        add_blocker(
            "health_score_low",
            f"Оценка здоровья {health_score}%, нужно минимум {SERVER_PUBLIC_MIN_HEALTH_SCORE}%.",
        )
    if protocol != "wireguard_udp":
        add_blocker(
            "client_protocol_not_ready",
            "Выдача конфигов клиентам сейчас готова только для основного слоя WireGuard UDP.",
        )
    if latest is None:
        add_blocker(
            "no_health_observation",
            "Нет наблюдения мониторинга по VPN-узлу, нельзя выдавать его пользователям.",
        )
    else:
        if latest.get("status") != "healthy":
            add_blocker(
                "latest_health_not_healthy",
                f"Последнее наблюдение мониторинга: {latest.get('status') or 'unknown'}.",
            )
        if latest_age_hours is None:
            add_blocker("latest_health_unparseable", "Не удалось разобрать время последней проверки.")
        elif latest_age_hours > SERVER_PUBLIC_OBSERVATION_MAX_AGE_HOURS:
            add_blocker(
                "latest_health_stale",
                (
                    f"Последняя проверка старше {SERVER_PUBLIC_OBSERVATION_MAX_AGE_HOURS} ч "
                    f"({latest_age_hours:.1f} ч)."
                ),
            )
    if healthy_24h < SERVER_PUBLIC_MIN_HEALTHY_OBSERVATIONS:
        add_blocker(
            "not_enough_healthy_observations",
            (
                f"Здоровых проверок за 24ч: {healthy_24h}, нужно минимум "
                f"{SERVER_PUBLIC_MIN_HEALTHY_OBSERVATIONS}."
            ),
        )
    if failed_24h > 0:
        add_blocker(
            "recent_failures_present",
            f"За последние 24ч есть проверки со сбоями или деградацией: {failed_24h}.",
        )

    if not config_readiness["ready"]:
        for blocker in config_readiness["blockers"]:
            add_blocker(blocker["code"], blocker["message"])

    return {
        "eligible": not blockers,
        "blockers": blockers,
        "clientConfigReadiness": config_readiness,
        "requirements": server_publication_requirements(),
        "latestObservationAt": latest.get("observedAt") if latest else None,
        "latestObservationStatus": latest.get("status") if latest else None,
        "latestObservationAgeHours": (
            round(float(latest_age_hours), 2) if latest_age_hours is not None else None
        ),
        "healthyObservations24h": healthy_24h,
        "failedObservations24h": failed_24h,
    }


def server_catalog_workflow_options() -> dict:
    return {
        "statuses": list(SERVER_CATALOG_STATUSES),
        "protocols": list(SERVER_CATALOG_PROTOCOLS),
        "transports": list(SERVER_CATALOG_TRANSPORTS),
        "clientConfigProfiles": [
            {
                "code": profile,
                "title": SERVER_CLIENT_CONFIG_PROFILE_TITLES.get(profile, profile),
                "description": {
                    "none": "Не выдавать клиентам, только inventory",
                    "builtin_wg0": "Только текущий backend wg0 endpoint",
                    "remote_ssh_wg0": "Отдельный WireGuard VPS через server-only SSH",
                }.get(profile, "Профиль выдачи клиентского конфига"),
            }
            for profile in SERVER_CLIENT_CONFIG_PROFILES
        ],
        "publicMode": "admin_preparation",
        "publicSafety": (
            "Управляемые записи остаются внутренним планом, пока у них нет явного "
            "профиля клиентского конфига, свежих проверок здоровья и релизного ревью."
        ),
        "safeDraftCreation": {
            "endpoint": "/api/v1/admin/server-catalog/draft-from-plan",
            "forcedDefaults": {
                "status": "draft",
                "isActive": False,
                "isPublic": False,
                "clientConfigProfile": "none",
                "protocol": "wireguard_udp",
                "transport": "udp",
                "healthScore": 0,
                "priority": 100,
            },
            "clientImpact": "Новый VPS сохраняется только как внутренний черновик и не попадает в клиентский каталог.",
        },
        "publicRequirements": server_publication_requirements(),
    }


def server_catalog_entry_payload(row: sqlite3.Row, health_meta: Optional[dict] = None) -> dict:
    health_meta = health_meta or {}
    eligibility = server_public_eligibility(row, health_meta)
    config_readiness = eligibility["clientConfigReadiness"]
    capacity = endpoint_capacity_payload(
        safe_row_int(row, "planned_bandwidth_mbps", SERVER_DEFAULT_BANDWIDTH_MBPS),
        safe_row_int(row, "reserved_bandwidth_mbps", SERVER_DEFAULT_RESERVED_MBPS),
        safe_row_int(row, "current_load_mbps", 0),
        safe_row_int(row, "active_clients", 0),
        safe_row_int(row, "assigned_users", 0),
        safe_row_text(row, "load_updated_at", ""),
    )
    selection_score = endpoint_selection_score(
        {
            "healthScore": int(row["health_score"] or 0),
            "latencyMs": int(row["latency_ms"]) if row["latency_ms"] is not None else None,
            "priority": int(row["priority"] or 100),
            "capacity": capacity,
        }
    )
    return {
        "id": int(row["id"]),
        "serverId": row["server_id"],
        "title": row["title"],
        "subtitle": row["subtitle"] or "",
        "country": row["country"],
        "city": row["city"] or "",
        "provider": row["provider"] or "",
        "host": row["host"],
        "port": int(row["port"]),
        "protocol": row["protocol"],
        "transport": row["transport"],
        "clientConfigProfile": config_readiness["profile"],
        "clientConfigProfileTitle": config_readiness["title"],
        "clientConfigReadiness": config_readiness,
        "status": row["status"],
        "healthScore": int(row["health_score"] or 0),
        "latencyMs": int(row["latency_ms"]) if row["latency_ms"] is not None else None,
        "priority": int(row["priority"] or 100),
        "capacity": capacity,
        "selectionScore": selection_score,
        "isActive": bool(row["is_active"]),
        "isPublic": bool(row["is_public"]),
        "publicationPausedAt": row["publication_paused_at"] or "",
        "publicationPausedReason": row["publication_paused_reason"] or "",
        "publicationPausedBy": row["publication_paused_by"] or "",
        "clientConfigReady": bool(config_readiness["ready"]),
        "available": bool(row["is_active"]) and row["status"] == "healthy",
        "publicEligible": bool(eligibility["eligible"]),
        "publicEligibility": eligibility,
        "publicBlockers": eligibility["blockers"],
        "latestObservation": health_meta.get("latest"),
        "latestObservationAt": eligibility["latestObservationAt"],
        "latestObservationStatus": eligibility["latestObservationStatus"],
        "latestObservationAgeHours": eligibility["latestObservationAgeHours"],
        "healthyObservations24h": eligibility["healthyObservations24h"],
        "failedObservations24h": eligibility["failedObservations24h"],
        "notes": row["notes"] or "",
        "createdAt": row["created_at"],
        "updatedAt": row["updated_at"],
    }


def list_managed_server_catalog_entries(
    status: Optional[str] = None,
    active: Optional[str] = None,
    public: Optional[str] = None,
    limit: int = 100,
    offset: int = 0,
) -> list[dict]:
    where = []
    params: list[object] = []
    if status and status != "all":
        where.append("status = ?")
        params.append(normalize_server_catalog_status(status))
    if active not in {None, "", "all"}:
        where.append("is_active = ?")
        params.append(1 if str(active).lower() in {"1", "true", "yes", "active"} else 0)
    if public not in {None, "", "all"}:
        where.append("is_public = ?")
        params.append(1 if str(public).lower() in {"1", "true", "yes", "public"} else 0)
    sql = "SELECT * FROM server_catalog_entries"
    if where:
        sql += " WHERE " + " AND ".join(where)
    sql += " ORDER BY priority ASC, id DESC LIMIT ? OFFSET ?"
    params.extend([max(1, min(int(limit or 100), 500)), max(0, int(offset or 0))])
    with db() as conn:
        rows = conn.execute(sql, tuple(params)).fetchall()
        health_meta = server_health_meta_for_entries(
            conn,
            [row["server_id"] for row in rows],
        )
    return [
        server_catalog_entry_payload(row, health_meta.get(row["server_id"]))
        for row in rows
    ]


def build_server_catalog_admin_summary(
    public_catalog: dict,
    managed_entries: list[dict],
) -> dict:
    blockers_by_code: dict[str, int] = {}
    for entry in managed_entries:
        for blocker in entry.get("publicBlockers") or []:
            code = blocker.get("code") or "unknown"
            blockers_by_code[code] = blockers_by_code.get(code, 0) + 1

    public_servers = public_catalog.get("servers") or []
    return {
        "publicClientServers": len(public_servers),
        "publicDefaultServerId": public_catalog.get("defaultServerId") or "",
        "managedTotal": len(managed_entries),
        "managedActive": sum(1 for entry in managed_entries if entry.get("isActive")),
        "managedPublicCandidates": sum(1 for entry in managed_entries if entry.get("isPublic")),
        "managedHealthy": sum(1 for entry in managed_entries if entry.get("status") == "healthy"),
        "managedClientConfigReady": sum(
            1 for entry in managed_entries if entry.get("clientConfigReady")
        ),
        "managedPublicEligible": sum(
            1 for entry in managed_entries if entry.get("publicEligible")
        ),
        "managedBlocked": sum(
            1 for entry in managed_entries if not entry.get("publicEligible")
        ),
        "blockersByCode": blockers_by_code,
        "mode": "safe_admin_preparation",
        "message": (
            "Публичный клиентский каталог пока намеренно выдаёт только проверенный "
            "встроенный VPN-узел. Управляемые VPN-узлы будут открыты клиентам после "
            "выдачи конфигов, свежих проверок здоровья и явного допуска."
        ),
    }


def build_server_publication_readiness(
    public_catalog: dict,
    managed_entries: list[dict],
) -> dict:
    summary = build_server_catalog_admin_summary(public_catalog, managed_entries)
    eligible_entries = [
        entry for entry in managed_entries if entry.get("publicEligible")
    ]
    blocked_entries = [
        {
            "serverId": entry.get("serverId"),
            "title": entry.get("title"),
            "status": entry.get("status"),
            "isActive": entry.get("isActive"),
            "isPublic": entry.get("isPublic"),
            "publicationPausedAt": entry.get("publicationPausedAt"),
            "publicationPausedReason": entry.get("publicationPausedReason"),
            "publicationPausedBy": entry.get("publicationPausedBy"),
            "healthScore": entry.get("healthScore"),
            "clientConfigProfile": entry.get("clientConfigProfile"),
            "clientConfigReady": entry.get("clientConfigReady"),
            "blockers": entry.get("publicBlockers") or [],
            "latestObservationAt": entry.get("latestObservationAt"),
            "latestObservationStatus": entry.get("latestObservationStatus"),
        }
        for entry in managed_entries
        if not entry.get("publicEligible")
    ]
    blockers_by_code = summary.get("blockersByCode") or {}
    next_actions: list[dict] = []

    if not managed_entries:
        next_actions.append(
            {
                "code": "add_managed_endpoint",
                "title": "Добавить первый управляемый VPN-узел",
                "owner": "admin",
                "detail": (
                    "Занеси новый VPS в каталог серверов как draft/internal. "
                    "Публичный клиент от этого не изменится."
                ),
            }
        )
    if blockers_by_code.get("client_config_profile_missing"):
        next_actions.append(
            {
                "code": "choose_client_config_profile",
                "title": "Выбрать профиль выдачи конфига",
                "owner": "codex",
                "detail": (
                    "Для текущего сервера можно выбрать builtin_wg0, для новых VPS "
                    "после server-only env доступен remote_ssh_wg0."
                ),
            }
        )
    if blockers_by_code.get("client_config_endpoint_mismatch"):
        next_actions.append(
            {
                "code": "implement_multi_endpoint_provisioning",
                "title": "Сделать выдачу конфигов для внешних VPN-узлов",
                "owner": "codex",
                "detail": (
                    "Для внешнего VPS нужен профиль remote_ssh_wg0 и server-only env на backend. "
                    "После этого всё равно нужны DNS, мониторинг и canary перед публикацией."
                ),
            }
        )
    if blockers_by_code.get("remote_node_config_missing") or blockers_by_code.get(
        "remote_node_ssh_key_not_found"
    ):
        next_actions.append(
            {
                "code": "configure_remote_node_env",
                "title": "Положить server-only env и SSH-ключ удалённого VPN-узла",
                "owner": "codex",
                "detail": (
                    "Файл /etc/bluevpn/vpn_nodes/<serverId>.env и SSH-ключ должны быть только "
                    "на backend-сервере, не в репозитории."
                ),
            }
        )
    if blockers_by_code.get("no_health_observation") or blockers_by_code.get(
        "not_enough_healthy_observations"
    ):
        next_actions.append(
            {
                "code": "add_monitoring_observations",
                "title": "Накопить проверки здоровья",
                "owner": "ops",
                "detail": (
                    "VPN-узел должен иметь свежие здоровые проверки за последние 24 часа, "
                    "иначе авто-выбор сервера будет небезопасным."
                ),
            }
        )
    if blockers_by_code.get("not_public_candidate"):
        next_actions.append(
            {
                "code": "mark_public_candidate_after_canary",
                "title": "Отметить VPN-узел кандидатом только после канареечной проверки",
                "owner": "admin",
                "detail": (
                    "Флаг public сейчас означает только кандидат на публикацию, "
                    "а не мгновенную выдачу пользователям."
                ),
            }
        )
    if not next_actions:
        next_actions.append(
            {
                "code": "ready_for_manual_review",
                "title": "Готово к ручному релизному ревью",
                "owner": "admin",
                "detail": (
                    "Перед публикацией всё равно нужны релизная проверка, поэтапная раскатка "
                    "и план отката."
                ),
            }
        )

    return {
        "ok": True,
        "version": APP_VERSION,
        "mode": "safe_admin_preparation",
        "canPublishManagedEndpoints": bool(eligible_entries),
        "publicCatalogUnchanged": True,
        "publicCatalogServerIds": [
            server.get("id") for server in public_catalog.get("servers") or []
        ],
        "defaultServerId": public_catalog.get("defaultServerId") or "",
        "publicationRules": server_publication_requirements(),
        "summary": summary,
        "eligibleManagedEntries": [
            {
                "serverId": entry.get("serverId"),
                "title": entry.get("title"),
                "healthScore": entry.get("healthScore"),
                "clientConfigProfile": entry.get("clientConfigProfile"),
                "latestObservationAt": entry.get("latestObservationAt"),
            }
            for entry in eligible_entries
        ],
        "blockedManagedEntries": blocked_entries,
        "nextActions": next_actions,
        "clientImpact": (
            "Публичный клиентский каталог серверов пока остаётся на встроенном VPN-узле "
            "intelligent_smew. Это намеренно защищает работающий VPN от случайной "
            "выдачи неподготовленного сервера."
        ),
    }


