@app.post("/api/v1/client/bootstrap")
def client_bootstrap(
    payload: BootstrapIn,
    authorization: Optional[str] = Header(default=None),
):
    user = get_user_by_token(authorization)

    device = ensure_device_row(
        user_id=user["id"],
        device_uid=payload.deviceUid.strip(),
        device_name=payload.deviceName.strip() or "Windows device",
        platform=payload.platform.strip() or "windows",
        app_version=payload.appVersion.strip() or "0.1.0",
    )
    touch_device(device["device_uid"], config_issued=False)

    sub = subscription_status(get_subscription_row(user["id"]))
    access_policy = client_subscription_access_policy(
        user,
        sub,
        client_marker=payload.clientMarker,
        release_channel=payload.releaseChannel,
    )
    effective_max_devices = int(access_policy["maxDevices"])
    if access_policy["paidBetaUser"]:
        sub = {**sub, "maxDevices": effective_max_devices}
    traffic_usage = subscription_traffic_usage_status(int(user["id"]), sub)

    with db() as conn:
        if access_policy["reason"] == "beta_cohort_required":
            count = enabled_device_count(conn, int(user["id"]))
        else:
            count = enforce_device_limit_for_current_device(
                conn,
                user_id=user["id"],
                current_device_uid=device["device_uid"],
                max_devices=effective_max_devices,
            )
        conn.commit()

    device_enabled = bool(device["is_enabled"])
    subscription_ok = bool(access_policy["allowed"])
    ad_gate = (
        disabled_ad_gate_policy(device["platform"], reason="product_no_ads")
        if access_policy["adsDisabled"]
        else free_ad_gate_policy(
            int(user["id"]),
            device["device_uid"],
            device["platform"],
            sub,
            app_version=device["app_version"],
        )
    )
    can_connect = (
        subscription_ok
        and count <= effective_max_devices
        and device_enabled
        and not ad_gate["required"]
    )

    reason = access_policy["reason"]
    if reason is None and count > effective_max_devices:
        reason = "device_limit_exceeded"
    elif reason is None and not device_enabled:
        reason = "device_disabled"
    elif reason is None and ad_gate["required"]:
        reason = "ad_reward_required"

    catalog = build_server_catalog(
        release_channel=payload.releaseChannel,
        app_version=device["app_version"],
        client_supported_protocols=payload.supportedProtocols,
    )
    resilience = catalog.get("resilience") or build_resilience_policy(catalog.get("servers"))
    route_decision = resilience.get("routeDecision") if isinstance(resilience, dict) else {}
    selected_server, endpoint_assignment = select_client_server_for_device(
        catalog,
        user_id=int(user["id"]),
        device_uid=device["device_uid"],
        requested_server_id="auto",
    )
    selected_endpoint = selected_server.get("endpoint") or {}
    client_resilience = client_route_probe_safe_resilience(
        resilience,
        platform=device["platform"],
        app_version=device["app_version"],
    )
    if access_policy["paidBetaClient"]:
        record_paid_beta_funnel_event(
            "bootstrap_allowed" if can_connect else "bootstrap_denied",
            user_id=int(user["id"]),
            device_uid=device["device_uid"],
            source=user["acquisition_source"],
            platform=device["platform"],
            app_version=device["app_version"],
            release_channel=payload.releaseChannel,
            metadata={"reason": reason, "canConnect": can_connect},
        )

    return {
        "ok": True,
        "canConnect": can_connect,
        "reason": reason,
        "device": {
            "deviceUid": device["device_uid"],
            "deviceName": device["device_name"],
            "platform": device["platform"],
            "appVersion": device["app_version"],
        },
        "subscription": sub,
        "accessPolicy": access_policy,
        "trafficUsage": traffic_usage,
        "server": {
            "id": selected_server.get("id") or "intelligent_smew",
            "name": selected_server.get("title") or "Green VPN",
            "endpoint": (
                f"{selected_endpoint.get('host') or WG_ENDPOINT_HOST}:"
                f"{selected_endpoint.get('port') or WG_ENDPOINT_PORT}"
            ),
        },
        "resilience": client_resilience,
        "endpointAssignment": endpoint_assignment,
        "rateLimitPolicy": sub.get("rateLimitPolicy"),
        "fairUsePolicy": sub.get("fairUsePolicy"),
        "adGate": ad_gate,
    }


@app.post("/api/v1/client/config")
def client_config(
    payload: ClientConfigIn,
    authorization: Optional[str] = Header(default=None),
):
    user = get_user_by_token(authorization)
    sub = subscription_status(get_subscription_row(user["id"]))
    access_policy = client_subscription_access_policy(
        user,
        sub,
        client_marker=payload.clientMarker,
        release_channel=payload.releaseChannel,
    )
    if not access_policy["allowed"]:
        code = str(access_policy["reason"] or "subscription_inactive")
        message = (
            "Для beta-доступа нужен персональный инвайт."
            if code == "beta_cohort_required"
            else "Beta Trial или оплаченный период завершён."
        )
        raise HTTPException(
            status_code=403,
            detail={
                "code": code,
                "message": message,
                "accessPolicy": access_policy,
            },
        )
    effective_max_devices = int(access_policy["maxDevices"])
    if access_policy["paidBetaUser"]:
        sub = {**sub, "maxDevices": effective_max_devices}
    traffic_usage = subscription_traffic_usage_status(int(user["id"]), sub)

    with db() as conn:
        device = conn.execute(
            "SELECT * FROM devices WHERE device_uid = ?",
            (payload.deviceUid.strip(),),
        ).fetchone()

    if device is None:
        raise HTTPException(status_code=404, detail="Device not found. Call bootstrap first.")

    if device["user_id"] != user["id"]:
        raise HTTPException(status_code=403, detail="Device belongs to another user.")

    if not bool(device["is_enabled"]):
        raise HTTPException(status_code=403, detail="Device disabled by admin.")

    with db() as conn:
        count = enforce_device_limit_for_current_device(
            conn,
            user_id=user["id"],
            current_device_uid=payload.deviceUid.strip(),
            max_devices=effective_max_devices,
        )
        conn.commit()

    if count > effective_max_devices:
        raise HTTPException(status_code=403, detail="Device limit exceeded.")

    ad_gate = (
        disabled_ad_gate_policy(device["platform"], reason="product_no_ads")
        if access_policy["adsDisabled"]
        else free_ad_gate_policy(
            int(user["id"]),
            payload.deviceUid.strip(),
            device["platform"],
            sub,
            app_version=device["app_version"],
        )
    )
    consumed_ad_grant = None
    if ad_gate["required"]:
        raise HTTPException(
            status_code=403,
            detail={
                "code": "ad_reward_required",
                "message": "Нужно посмотреть рекламу перед подключением бесплатного режима.",
                "adGate": ad_gate,
            },
        )

    catalog = build_server_catalog(
        release_channel=payload.releaseChannel,
        app_version=device["app_version"],
        client_supported_protocols=payload.supportedProtocols,
    )
    resilience = catalog.get("resilience") or build_resilience_policy(catalog.get("servers"))
    route_decision = resilience.get("routeDecision") if isinstance(resilience, dict) else {}
    selected_route = route_decision.get("selected") if isinstance(route_decision, dict) else {}
    selected_server, endpoint_assignment = select_client_server_for_device(
        catalog,
        user_id=int(user["id"]),
        device_uid=payload.deviceUid.strip(),
        requested_server_id=payload.serverId,
    )
    selected_protocol = server_primary_protocol(selected_server)

    if selected_protocol in {"naive_https", "dnstt"}:
        selected_server_id = str(selected_server.get("id") or "").strip()
        selected_row = get_managed_server_catalog_row_by_server_id(selected_server_id)
        expected_profile = {
            "naive_https": "static_naive_https_canary",
            "dnstt": "static_dnstt_canary",
        }[selected_protocol]
        if (
            selected_row is None
            or server_row_client_config_profile(selected_row) != expected_profile
        ):
            raise HTTPException(
                status_code=409,
                detail=f"Guarded {selected_protocol} config profile is not configured.",
            )
        selected_endpoint = selected_server.get("endpoint") or {}
        if selected_protocol == "naive_https":
            static_config = load_naive_https_client_config(
                selected_server_id,
                row_host=str(selected_endpoint.get("host") or ""),
                row_port=int(selected_endpoint.get("port") or 0),
            )
            config_format = "naive-https-json"
        else:
            static_config = load_dnstt_client_config(
                selected_server_id,
                row_host=str(selected_endpoint.get("host") or ""),
                row_port=int(selected_endpoint.get("port") or 0),
            )
            config_format = "dnstt-json"
        touch_device(device["device_uid"], config_issued=True)
        if (
            not access_policy["adsDisabled"]
            and FREE_AD_GATE_ENABLED
            and free_ad_gate_required_for(
                sub,
                device["platform"],
                device["app_version"],
            )
        ):
            consumed_ad_grant = consume_free_access_grant(
                int(user["id"]),
                device["device_uid"],
            )
        config_resilience = client_route_probe_safe_resilience(
            {
                "selectedBy": endpoint_assignment.get("selectedBy") or "auto",
                "strategy": "guarded_preview_cascade",
                "selectedProtocol": selected_protocol,
                "routeDecision": route_decision,
                "clientReadyProtocols": sorted(SERVER_CLIENT_READY_PROTOCOLS),
            },
            platform=device["platform"],
            app_version=device["app_version"],
        )
        return {
            "ok": True,
            "protocol": selected_protocol,
            "configFormat": config_format,
            "configText": static_config["configText"],
            "deviceUid": device["device_uid"],
            "assignedIp": None,
            "endpoint": f"{static_config['host']}:{static_config['port']}",
            "serverId": selected_server_id,
            "clientConfigProfile": expected_profile,
            "resilience": config_resilience,
            "endpointAssignment": endpoint_assignment,
            "rateLimitPolicy": sub.get("rateLimitPolicy"),
            "fairUsePolicy": sub.get("fairUsePolicy"),
            "trafficUsage": traffic_usage,
            "supportConfigRefreshApplied": False,
            "subscription": sub,
            "accessPolicy": access_policy,
            "adGate": {
                **ad_gate,
                "grantConsumed": consumed_ad_grant is not None,
                "consumedGrant": consumed_ad_grant,
            },
        }

    if selected_protocol == "hysteria2":
        selected_server_id = str(selected_server.get("id") or "").strip()
        selected_row = get_managed_server_catalog_row_by_server_id(selected_server_id)
        if (
            selected_row is None
            or server_row_client_config_profile(selected_row) != "static_hysteria2_canary"
        ):
            raise HTTPException(
                status_code=409,
                detail="Для выбранного Hysteria2 canary не настроен безопасный профиль выдачи.",
            )
        selected_endpoint = selected_server.get("endpoint") or {}
        hysteria_config = load_hysteria2_client_config(
            selected_server_id,
            row_host=str(selected_endpoint.get("host") or ""),
            row_port=int(selected_endpoint.get("port") or 0),
        )
        touch_device(device["device_uid"], config_issued=True)
        if (
            not access_policy["adsDisabled"]
            and FREE_AD_GATE_ENABLED
            and free_ad_gate_required_for(
                sub,
                device["platform"],
                device["app_version"],
            )
        ):
            consumed_ad_grant = consume_free_access_grant(
                int(user["id"]),
                device["device_uid"],
            )
        config_resilience = client_route_probe_safe_resilience(
            {
                "selectedBy": endpoint_assignment.get("selectedBy") or "auto",
                "strategy": "capacity_aware_sticky_endpoint",
                "selectedProtocol": selected_protocol,
                "routeDecision": route_decision,
                "clientReadyProtocols": sorted(SERVER_CLIENT_READY_PROTOCOLS),
            },
            platform=device["platform"],
            app_version=device["app_version"],
        )
        return {
            "ok": True,
            "protocol": selected_protocol,
            "configFormat": "hysteria2-yaml",
            "configText": hysteria_config["configText"],
            "deviceUid": device["device_uid"],
            "assignedIp": None,
            "endpoint": f"{hysteria_config['host']}:{hysteria_config['port']}",
            "serverId": selected_server_id,
            "clientConfigProfile": "static_hysteria2_canary",
            "resilience": config_resilience,
            "endpointAssignment": endpoint_assignment,
            "rateLimitPolicy": sub.get("rateLimitPolicy"),
            "fairUsePolicy": sub.get("fairUsePolicy"),
            "trafficUsage": traffic_usage,
            "supportConfigRefreshApplied": False,
            "subscription": sub,
            "accessPolicy": access_policy,
            "adGate": {
                **ad_gate,
                "grantConsumed": consumed_ad_grant is not None,
                "consumedGrant": consumed_ad_grant,
            },
        }

    if selected_protocol == "vless_reality":
        selected_server_id = str(selected_server.get("id") or "").strip()
        selected_row = get_managed_server_catalog_row_by_server_id(selected_server_id)
        if (
            selected_row is None
            or server_row_client_config_profile(selected_row) != "static_vless_reality_canary"
        ):
            raise HTTPException(
                status_code=409,
                detail="Для выбранного VLESS REALITY canary не настроен безопасный профиль выдачи.",
            )
        selected_endpoint = selected_server.get("endpoint") or {}
        vless_reality_config = load_vless_reality_client_config(
            selected_server_id,
            row_host=str(selected_endpoint.get("host") or ""),
            row_port=int(selected_endpoint.get("port") or 0),
        )
        touch_device(device["device_uid"], config_issued=True)
        if (
            not access_policy["adsDisabled"]
            and FREE_AD_GATE_ENABLED
            and free_ad_gate_required_for(
                sub,
                device["platform"],
                device["app_version"],
            )
        ):
            consumed_ad_grant = consume_free_access_grant(
                int(user["id"]),
                device["device_uid"],
            )
        config_resilience = client_route_probe_safe_resilience(
            {
                "selectedBy": endpoint_assignment.get("selectedBy") or "auto",
                "strategy": "capacity_aware_sticky_endpoint",
                "selectedProtocol": selected_protocol,
                "routeDecision": route_decision,
                "clientReadyProtocols": sorted(SERVER_CLIENT_READY_PROTOCOLS),
            },
            platform=device["platform"],
            app_version=device["app_version"],
        )
        return {
            "ok": True,
            "protocol": selected_protocol,
            "configFormat": "xray-json",
            "configText": vless_reality_config["configText"],
            "deviceUid": device["device_uid"],
            "assignedIp": None,
            "endpoint": (
                f"{vless_reality_config['host']}:{vless_reality_config['port']}"
            ),
            "serverId": selected_server_id,
            "clientConfigProfile": "static_vless_reality_canary",
            "resilience": config_resilience,
            "endpointAssignment": endpoint_assignment,
            "rateLimitPolicy": sub.get("rateLimitPolicy"),
            "fairUsePolicy": sub.get("fairUsePolicy"),
            "trafficUsage": traffic_usage,
            "supportConfigRefreshApplied": False,
            "subscription": sub,
            "accessPolicy": access_policy,
            "adGate": {
                **ad_gate,
                "grantConsumed": consumed_ad_grant is not None,
                "consumedGrant": consumed_ad_grant,
            },
        }

    support_refresh_requested = bool(device["support_config_refresh_requested_at"])
    refresh_result: Optional[dict] = None
    if support_refresh_requested:
        refresh_result = reissue_device_keys_and_ip(payload.deviceUid.strip())
        device = refresh_result["device"]
    else:
        device = ensure_device_keys_and_ip(payload.deviceUid.strip())

    client_public_key = device["client_public_key"]
    client_private_key = device["client_private_key"]
    preshared_key = device["preshared_key"]
    assigned_ip = device["assigned_ip"]
    if selected_protocol == "amneziawg":
        selected_server_id = str(selected_server.get("id") or "").strip()
        selected_row = get_managed_server_catalog_row_by_server_id(selected_server_id)
        if selected_row is None or server_row_client_config_profile(selected_row) != "remote_ssh_awg2":
            raise HTTPException(
                status_code=409,
                detail="Для выбранного AWG2-узла не настроен безопасный профиль выдачи.",
            )
        selected_remote_config = load_remote_vpn_node_config(selected_server_id)
        assigned_ip = ensure_device_transport_ip(
            device["device_uid"],
            transport_key=selected_protocol,
            client_subnet=selected_remote_config.get("clientSubnet") or "",
        )

    old_public_key = (
        clean_limited_text(refresh_result.get("oldPublicKey"), 120).strip()
        if refresh_result is not None
        else ""
    )
    try:
        provisioning = provision_wireguard_peer_for_selected_server(
            selected_server,
            device_uid=device["device_uid"],
            public_key=client_public_key,
            psk=preshared_key,
            ip=assigned_ip,
            old_public_key=old_public_key,
            previous_server_id=endpoint_assignment.get("previousServerId"),
        )
    except HTTPException:
        raise
    except (subprocess.CalledProcessError, OSError, TimeoutError):
        raise HTTPException(
            status_code=503,
            detail={
                "code": "vpn_node_provisioning_failed",
                "message": "VPN-узел временно недоступен. Попробуйте другой сервер или авто-подбор.",
                "serverId": selected_server.get("id") or "intelligent_smew",
            },
        )
    support_refresh_applied = refresh_result is not None
    if support_refresh_applied:
        refresh_reason = clean_limited_text(refresh_result.get("reason"), 500).strip()
        clear_support_config_refresh_after_issue(device["device_uid"], refresh_reason)
        write_admin_audit(
            "support_config_refresh_applied",
            "device",
            device["device_uid"],
            {
                "deviceUid": device["device_uid"],
                "requestedAt": refresh_result.get("requestedAt"),
                "requestedBy": refresh_result.get("requestedBy"),
                "reason": refresh_reason or "support_requested_config_refresh",
                "rotatedClientKeys": True,
            },
            actor="backend_config_fetch",
        )

    config_text = build_client_config(
        client_private_key=client_private_key,
        preshared_key=preshared_key,
        server_public_key=provisioning["serverPublicKey"],
        client_ip=assigned_ip,
        endpoint_host=provisioning["endpointHost"],
        endpoint_port=provisioning["endpointPort"],
        client_mtu=provisioning.get("clientMtu"),
        interface_fields=provisioning.get("interfaceFields"),
    )
    touch_device(device["device_uid"], config_issued=True)
    if (
        not access_policy["adsDisabled"]
        and FREE_AD_GATE_ENABLED
        and free_ad_gate_required_for(
        sub,
        device["platform"],
        device["app_version"],
        )
    ):
        consumed_ad_grant = consume_free_access_grant(int(user["id"]), device["device_uid"])

    config_resilience = client_route_probe_safe_resilience(
        {
            "selectedBy": endpoint_assignment.get("selectedBy") or "auto",
            "strategy": "capacity_aware_sticky_endpoint",
            "selectedProtocol": (selected_route or {}).get("protocol") or "wireguard_udp",
            "routeDecision": route_decision,
            "clientReadyProtocols": sorted(SERVER_CLIENT_READY_PROTOCOLS),
        },
        platform=device["platform"],
        app_version=device["app_version"],
    )

    return {
        "ok": True,
        "protocol": selected_protocol,
        "configFormat": "awg-quick" if selected_protocol == "amneziawg" else "wg-quick",
        "configText": config_text,
        "deviceUid": device["device_uid"],
        "assignedIp": assigned_ip,
        "endpoint": (
            f"{(selected_server.get('endpoint') or {}).get('host') or WG_ENDPOINT_HOST}:"
            f"{(selected_server.get('endpoint') or {}).get('port') or WG_ENDPOINT_PORT}"
        ),
        "serverId": selected_server["id"] if selected_server else "intelligent_smew",
        "clientConfigProfile": provisioning["profile"],
        "resilience": config_resilience,
        "endpointAssignment": endpoint_assignment,
        "rateLimitPolicy": sub.get("rateLimitPolicy"),
        "fairUsePolicy": sub.get("fairUsePolicy"),
        "trafficUsage": traffic_usage,
        "supportConfigRefreshApplied": support_refresh_applied,
        "subscription": sub,
        "accessPolicy": access_policy,
        "adGate": {
            **ad_gate,
            "grantConsumed": consumed_ad_grant is not None,
            "consumedGrant": consumed_ad_grant,
        },
    }


